import sys

def main():
    rows = sys.stdin.read().split()[:9]
    seen = set()
    for r in range(9):
        for c in range(9):
            ch = rows[r][c]
            if ch == '.':
                continue
            keys = (('r', r, ch), ('c', c, ch), ('b', r // 3, c // 3, ch))
            for k in keys:
                if k in seen:
                    print('false')
                    return
            seen.update(keys)
    print('true')

